draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

var floorY = H*0.82, shelfY = H*0.22;
var ax = W*0.16, bx = W*0.62;

// ground
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(W*0.05, floorY); ctx.lineTo(W*0.95, floorY); ctx.stroke();

// shelf
ctx.fillStyle = C.faint;
ctx.fillRect(W*0.50, shelfY, W*0.30, 5);
ctx.fillStyle = C.ink;
ctx.fillText("shelf", W*0.50, shelfY - 8);

// height marker
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(W*0.90, floorY); ctx.lineTo(W*0.90, shelfY); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("h", W*0.905, (floorY + shelfY)/2);

// path 1: straight up then across
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(ax, floorY);
ctx.lineTo(ax, shelfY - 26);
ctx.lineTo(bx, shelfY - 26);
ctx.lineTo(bx, shelfY - 4);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("path 1", ax + 6, shelfY - 34);

// path 2: wandering
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(ax, floorY);
var i, s, qx, qy;
for (i = 1; i <= 60; i++) {
  s = i/60;
  qx = ax + (bx - ax)*s;
  qy = floorY - (floorY - shelfY + 4)*s + Math.sin(s*3.3*Math.PI)*H*0.11*(1 - s*0.4);
  ctx.lineTo(qx, qy);
}
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("path 2", W*0.30, floorY - 12);

// book
ctx.fillStyle = C.figure;
ctx.fillRect(bx - 13, shelfY - 20, 26, 18);
ctx.fillStyle = C.ink;
ctx.fillText("book, mass m", bx + 18, shelfY - 8);

// start marker
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(ax, floorY, 4, 0, Math.PI*2); ctx.fill();
ctx.fillText("start", ax - 12, floorY + 16);

// verdict
ctx.fillStyle = C.ink;
ctx.fillText("gravity does -mgh along either path, so U = mgh is a function of height alone", W*0.06, H*0.96);

out.note = "Change of gravitational potential energy depends only on the change in height.";
